"use client";

import { useState } from "react";
import { winEdgeInfo, rawModelWinProb } from "@/lib/winprob";

/**
 * Share a pick as a branded card link (/share renders the card; its OG
 * image is generated by /api/share-card, so the link unfurls as a proper
 * MoyLine AI card in Messages, WhatsApp, X, etc.). Uses the native share
 * sheet when available and falls back to copying the link. Member-driven
 * word-of-mouth — the /share page is noindex and carries no card data
 * beyond the single pick the member chose to share.
 */
export default function ShareButton({
  game,
  play,
  price,
  edgeCents,
  winProb,
  star = false,
  dateLabel,
  starts,
}: {
  game: string;
  play: string;
  price?: string;
  edgeCents?: number | null;
  winProb?: number | null;
  star?: boolean;
  dateLabel?: string;
  starts?: string;
}) {
  const [copied, setCopied] = useState(false);

  async function share() {
    const params = new URLSearchParams();
    params.set("g", game);
    params.set("p", play);
    if (price) params.set("pr", price);
    // Members see win% + edge, never the internal 1–5 confidence:
    // w = RAW model win prob (whole %), e = edge in cents. Raw, not the
    // fitted display %: /share and /api/share-card re-derive the badge
    // through winEdgeInfo, which applies the calibration fit — sending
    // the fitted number would double-fit it on arrival.
    const input = { price, edge_cents: edgeCents, win_prob: winProb };
    const info = winEdgeInfo(input);
    if (info) {
      const rawW = rawModelWinProb(input);
      if (rawW !== null) params.set("w", String(rawW));
      if (info.edgeCents !== null && info.edgeCents !== 0)
        params.set("e", String(info.edgeCents));
    }
    if (star) params.set("s", "1");
    if (dateLabel) params.set("d", dateLabel);
    if (starts) params.set("t", starts);
    const url = `${window.location.origin}/share?${params.toString()}`;
    const text = `${star ? "★ " : ""}${play}${price ? ` ${price}` : ""} — ${game} · MoyLine AI`;

    if (typeof navigator !== "undefined" && "share" in navigator) {
      try {
        await navigator.share({ title: "MoyLine AI pick", text, url });
        return;
      } catch (e) {
        // Member closed the share sheet — not an error, don't fall through.
        if (e instanceof Error && e.name === "AbortError") return;
      }
    }
    try {
      await navigator.clipboard.writeText(`${text}\n${url}`);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      /* clipboard unavailable (permissions) — nothing more to do */
    }
  }

  return (
    <button
      onClick={share}
      className="text-xs font-bold px-3 py-1.5 rounded-full border border-line text-muted hover:border-gold hover:text-gold transition-colors"
      title="Share this pick as a branded card"
    >
      {copied ? "✓ Link copied" : "Share ↗"}
    </button>
  );
}
